package com.example.pryanik.commands;

import com.example.pryanik.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.player.AsyncPlayerChatEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;

public final class HomeCommand implements CommandExecutor,Listener {
 private static final String PERSONAL_MENU="§8Мои дома",CLAN_MENU="§8Дом клана";
 private final PryanikPlugin plugin;private final String command;private final Map<UUID,String> pendingNames=new ConcurrentHashMap<>();
 public HomeCommand(PryanikPlugin plugin,String command){this.plugin=plugin;this.command=command;}
 private ItemStack icon(Material mat,String name,String... lore){ItemStack i=new ItemStack(mat);ItemMeta m=i.getItemMeta();m.setDisplayName(name);m.setLore(Arrays.asList(lore));i.setItemMeta(m);return i;}
 @Override public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Только игрок.");return true;}if(!plugin.authed(p.getUniqueId())){p.sendMessage("§cСначала войдите.");return true;}if(plugin.gameModes().isSpawnWorld(p.getWorld())){p.sendMessage("§cДома в мире спавна недоступны.");return true;}if(plugin.inCombat(p.getUniqueId())){p.sendMessage("§cНельзя использовать /"+command+" в бою.");return true;}try{if(command.equals("home")){if(plugin.clanScope(p).startsWith("anarchy_")){p.sendMessage("§cЛичные дома в анархии отключены.");return true;}if(a.length>0){String[] h=plugin.db().namedHome(p.getUniqueId(),a[0],p.getWorld().getName());if(h==null){p.sendMessage("§cДом «§e"+a[0]+"§c» не найден в этом грифе.");return true;}return teleport(p,h[1],new double[]{Double.parseDouble(h[2]),Double.parseDouble(h[3]),Double.parseDouble(h[4]),Double.parseDouble(h[5]),Double.parseDouble(h[6])},h[0]);}openPersonal(p);return true;}if(plugin.clanScope(p).equals("legacy")){p.sendMessage("§cДом клана доступен только в lobby или игровом грифе.");return true;}Clan clan=plugin.db().clan(p.getUniqueId(),plugin.clanScope(p));if(clan==null){p.sendMessage("§cСначала вступите в клан.");return true;}openClan(p,clan);}catch(Exception e){p.sendMessage("§cНе удалось открыть меню домов.");plugin.getLogger().warning("Home menu: "+e);}return true;}
 private void openPersonal(Player p)throws Exception{Inventory inv=Bukkit.createInventory(null,54,PERSONAL_MENU);inv.setItem(49,icon(Material.EMERALD,"§aСоздать дом","§7Имя будет запрошено в чате"));List<String[]> homes=plugin.db().namedHomes(p.getUniqueId(),p.getWorld().getName());int slot=0;for(String[] h:homes){if(slot>=45)break;inv.setItem(slot++,icon(Material.RED_BED,"§e"+h[0],"§7Мир: "+h[1],"§cЛКМ: телепорт","§cПКМ: удалить"));}p.openInventory(inv);}
 private void openClan(Player p,Clan clan){Inventory inv=Bukkit.createInventory(null,27,CLAN_MENU);if(clan.hasHome()){inv.setItem(11,icon(Material.BEACON,"§aТелепорт домой клана","§7Нажмите для телепорта"));if(clan.leader().equals(p.getUniqueId()))inv.setItem(15,icon(Material.BARRIER,"§cУдалить дом клана","§7Удаление доступно лидеру"));}else inv.setItem(13,icon(Material.GRAY_DYE,"§7Дом клана не задан"));if(clan.leader().equals(p.getUniqueId()))inv.setItem(22,icon(Material.EMERALD,"§aСоздать/обновить дом","§7Сохранить текущее место","§7Имя будет запрошено в чате"));p.openInventory(inv);}
 private void promptName(Player p){pendingNames.put(p.getUniqueId(),command);p.closeInventory();p.sendMessage("§eНапишите в чат название дома (латиница, цифры, _ или -, до 20 символов). Отмена: cancel.");}
 @EventHandler public void nameChat(AsyncPlayerChatEvent e){Player p=e.getPlayer();String type=pendingNames.remove(p.getUniqueId());if(type==null)return;e.setCancelled(true);String name=e.getMessage().trim();if(name.equalsIgnoreCase("cancel")){p.sendMessage("§cСоздание дома отменено.");return;}if(!name.matches("[A-Za-z0-9_-]{1,20}")){p.sendMessage("§cНазвание: латиница, цифры, _ или -, до 20 символов. Введите снова или cancel.");pendingNames.put(p.getUniqueId(),type);return;}Bukkit.getScheduler().runTask(plugin,()->{try{if(!plugin.authed(p.getUniqueId()))return;Location x=p.getLocation();if(type.equals("home")){if(plugin.clanScope(p).startsWith("anarchy_")){p.sendMessage("§cЛичные дома отключены в анархии.");return;}plugin.db().saveNamedHome(p.getUniqueId(),name,x.getWorld().getName(),x.getX(),x.getY(),x.getZ(),x.getYaw(),x.getPitch());p.sendMessage("§aДом «§e"+name+"§a» сохранён.");openPersonal(p);}else{Clan clan=plugin.db().clan(p.getUniqueId(),plugin.clanScope(p));if(clan==null){p.sendMessage("§cКлан не найден в этом грифе.");return;}if(!clan.leader().equals(p.getUniqueId())){p.sendMessage("§cТолько лидер клана может задать дом.");return;}if(!plugin.clanScope(p).equals(plugin.db().clanScope(clan.id()))){p.sendMessage("§cДом клана доступен только в его грифе.");return;}plugin.db().setClanHome(clan.id(),x.getWorld().getName(),x.getX(),x.getY(),x.getZ(),x.getYaw(),x.getPitch());plugin.db().setClanHomeName(clan.id(),name);p.sendMessage("§aДом клана «§e"+name+"§a» сохранён.");openClan(p,plugin.db().clan(p.getUniqueId(),plugin.clanScope(p)));}}catch(Exception ex){p.sendMessage("§cОшибка сохранения дома.");plugin.getLogger().warning("Save named home: "+ex);}});}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;String title=e.getView().getTitle();if(!PERSONAL_MENU.equals(title)&&!CLAN_MENU.equals(title))return;e.setCancelled(true);if(!plugin.authed(p.getUniqueId())){p.closeInventory();return;}if(e.getRawSlot()>=e.getView().getTopInventory().getSize())return;try{if(PERSONAL_MENU.equals(title)){int slot=e.getRawSlot();if(slot==49){promptName(p);return;}ItemStack clicked=e.getCurrentItem();if(clicked==null||!clicked.hasItemMeta())return;String name=ChatColor.stripColor(clicked.getItemMeta().getDisplayName());if(name==null)return;if(e.isRightClick()){plugin.db().deleteNamedHome(p.getUniqueId(),name,p.getWorld().getName());p.sendMessage("§aДом удалён.");openPersonal(p);}else if(e.isLeftClick()){String[] h=plugin.db().namedHome(p.getUniqueId(),name,p.getWorld().getName());if(h==null)return;teleport(p,h[1],new double[]{Double.parseDouble(h[2]),Double.parseDouble(h[3]),Double.parseDouble(h[4]),Double.parseDouble(h[5]),Double.parseDouble(h[6])},name);}}else{Clan clan=plugin.db().clan(p.getUniqueId(),plugin.clanScope(p));if(clan==null)return;int slot=e.getRawSlot();if(slot==22&&clan.leader().equals(p.getUniqueId())){promptName(p);return;}if(slot==15&&clan.leader().equals(p.getUniqueId())){plugin.db().deleteClanHome(clan.id());p.sendMessage("§aДом клана удалён.");openClan(p,plugin.db().clan(p.getUniqueId(),plugin.clanScope(p)));return;}if(slot==11&&clan.hasHome())teleport(p,clan.homeWorld(),new double[]{clan.homeX(),clan.homeY(),clan.homeZ(),clan.homeYaw(),clan.homePitch()},"дом клана");}}catch(Exception ex){p.sendMessage("§cОшибка управления домом.");plugin.getLogger().warning("Home GUI: "+ex);}}
 @EventHandler public void quit(PlayerQuitEvent e){pendingNames.remove(e.getPlayer().getUniqueId());}
 private boolean teleport(Player p,String world,double[] h,String label){World w=Bukkit.getWorld(world);if(plugin.gameModes().isModeWorld(p.getWorld())&&(w==null||!Objects.equals(plugin.instanceOf(p.getWorld().getName()),plugin.instanceOf(w.getName())))){p.sendMessage("§cНельзя телепортироваться за пределы текущего грифа.");return true;}if(w==null){p.sendMessage("§cМир дома не загружен: "+world);return true;}p.closeInventory();p.teleport(new Location(w,h[0],h[1],h[2],(float)h[3],(float)h[4]));p.sendMessage("§aТелепортация: "+label+".");return true;}
}
